const today = () => new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jakarta',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function newProject(name='') { return {id:crypto.randomUUID(),name,ma:'',subMa:'',workUnit:'',programCategory:'',budget:null,owner:'',location:'',date:today(),year:'',coordinates:'',documentType:'RAB',resourceMeta:{},overhead:10,tax:12,taxScheme:'dpp11of12',items:[],rates:{},smkk:[],smkkRisk:'',smkkSettings:{workers:null,months:null,insuredValue:null,highway:false},smkkDrafts:{}}; }
let projects = [newProject()], active = 0, catalog = [], documents = [], query = '', field = 'Semua', priceGroup = 'Semua', priceQuery = '', manualRows = [], quantitySelectedId='', compactProjectOpen=false, informationStage='choice', allowInformationFormEntry=false, workUnitOptions=[], catalogLimit=48,pickerLimit=48,catalogStatus='Semua',coverage=null,smkkTemplates=null,smkkOpenGroups=new Set(['1']),smkkExpanded=false,pendingSmkkFocus=false,toastTimer;
try {
  const stored = JSON.parse(localStorage.getItem('ahsp-rab-v1'));
  if (stored?.projects?.length && stored.projects.length <= 100) {
    projects = stored.projects.map(validateProject); active = Math.min(Math.max(0,Number(stored.active)||0),projects.length-1);
  }
} catch { /* Preserve existing storage until the user makes a change. */ }
const project = () => projects[active];
function save() {
  try {localStorage.setItem('ahsp-rab-v1',JSON.stringify({version:1,projects,active}));$('#save-state')?.replaceChildren(document.createTextNode('Tersimpan di browser'));}
  catch {notify('Penyimpanan browser penuh/tidak tersedia. Segera ekspor cadangan proyek.');}
}
function notify(text) {$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
function view() {return ['project','quantity','recap','rab','catalog','prices','resources','assistant'].includes(location.hash.slice(1))?location.hash.slice(1):'rab';}
const names = {project:'Informasi Umum',quantity:'Quantity Pekerjaan',recap:'Rekapitulasi RAB',rab:'Rencana Anggaran Biaya (RAB)',catalog:'Analisa Harga Satuan (AHS)',prices:'Harga Satuan Dasar (HSD)',assistant:'Asisten AI',resources:'Rekap Sumber Daya'};
const sidebarRoutes=['project','quantity','recap','rab','catalog','prices','assistant'];
function nav(){ $('#navigation').innerHTML=sidebarRoutes.map(key=>`<a href="#${key}" ${view()===key?'class="active" aria-current="page"':''}><span class="nav-symbol">${symbols[key]}</span><span>${names[key]}</span>${key==='rab'?`<span class="nav-count">${project().items.filter(i=>!i.heading).length}</span>`:''}</a>`).join('')+'<a href="references.html#library" target="_blank" rel="noopener"><span class="nav-symbol">→</span><span>Dasar-dasar Perhitungan (Pustaka)</span></a>';$('#breadcrumb-current').textContent=names[view()]; }
function header(title,description,actions=''){return `<div class="rab-heading"><div><div class="eyebrow">AHSP SE DJBK NO. 47 TAHUN 2026</div><h1>${title}</h1><p>${description}</p></div><div class="action-row">${actions}</div></div>`;}
function sourceLink(item){if(item.empirical)return 'AHS Empiris · dasar pengamatan/perhitungan pengguna';return item.docId?`<a href="documents/${esc(item.docId)}.pdf#page=${item.page}" target="_blank" rel="noopener">Lampiran ${item.docId.toUpperCase()} · PDF hal. ${item.page} →</a>`:'Analisis manual';}
function taxName(p=project()){return p.taxScheme==='dpp11of12'?'PPN':'Pajak tarif langsung';}
function dppName(p=project()){return p.taxScheme==='dpp11of12'?'DPP 11/12 × (pekerjaan + SMKK)':'Dasar pengenaan pajak (100%)';}
function exportActions(){return '<button class="button subtle" data-action="backup">Cadangkan JSON ↓</button><button class="button subtle" data-action="csv">Ekspor RAB CSV ↓</button><button class="button" data-action="print">Cetak / PDF →</button>';}
function projectBar(){return `<div class="project-switch"><label>PROYEK AKTIF<select id="project-select">${projects.map((p,i)=>`<option value="${i}" ${i===active?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><button class="button subtle" data-action="new">+ Proyek baru</button><button class="text-action" data-action="import-project">Impor cadangan</button><span id="save-state">Tersimpan di browser</span></div>`;}
function sheet(){const p=project(),r=calculateProject(p);return compactProjectToolbar()+`<div class="section-heading rab-section-heading"><div><h2>Daftar pekerjaan</h2><p>Susun WBS A → 1 → a → •. Ketik uraian, pilih AHS, lalu isi volume dan keterangan.</p></div><div class="action-row"><button class="button subtle" data-action="add-heading">+ Lingkup Pekerjaan</button><button class="button" data-action="add-description">+ Tambah uraian pekerjaan</button></div></div>${r.smkkMissing?`<div class="rab-alert">${r.smkkMissing} komponen SMKK aktif belum lengkap. Lengkapi pada AHS SMKK. <button class="text-action" data-action="open-smkk">Buka AHS SMKK →</button></div>`:''}${r.missing?`<div class="rab-alert">${r.missing} harga dasar belum diisi. Total masih parsial. <a href="#prices">Lengkapi harga dasar →</a></div>`:''}${formHeader(p,'RENCANA ANGGARAN BIAYA (RAB)')}${wbsTable(p,r)}<div class="budget-bottom"><aside class="budget-summary"><div class="eyebrow">REKAPITULASI BIAYA</div>${budgetSummaryHtml(p,r)}<p>${r.incomplete?'DRAF — lengkapi harga dasar, volume dan rincian SMKK sebelum menggunakan hasil sebagai anggaran final.':'Seluruh harga dasar terisi. Tinjau volume, spesifikasi, metode, serta perlakuan pajak proyek.'}</p></aside></div>`;}
const catalogState=a=>({verified:'Diperiksa',extracted:'Ekstraksi · perlu diperiksa',review:'Perlu lengkapi / parameter',reference:'Rujukan sumber'}[a.extractionStatus]||'Diperiksa');
function catalogView(){const counts=catalog.reduce((r,a)=>(r[a.extractionStatus||'verified']=(r[a.extractionStatus||'verified']||0)+1,r),{});return header('Analisa Harga Satuan (AHS)',`${fmt(catalog.length)} entri sumber SE DJBK 2026. ${fmt(counts.verified||0)} template diperiksa; entri ekstraksi dan rujukan dibuka untuk pemeriksaan sebelum dipakai.`,'<button class="button subtle" data-action="open-smkk">Biaya SMKK ↓</button><button class="button" data-action="empirical">+ AHS Empiris</button><button class="button subtle" data-action="manual">+ Analisis manual</button>')+`<details class="catalog-coverage"><summary>Cakupan katalog per lampiran</summary>${coverage?`<table><thead><tr><th>Lampiran</th><th>Kode daftar isi tercakup</th><th>Tabel terdeteksi / masuk katalog</th></tr></thead><tbody>${coverage.documents.map(d=>`<tr><td>${fieldName(d.docId)}</td><td>${fmt(d.tocRepresented)} / ${fmt(d.tocCodes)}</td><td>${fmt(d.catalogTables)} / ${fmt(d.detectedTables)}</td></tr>`).join('')}</tbody></table>`:''}<p>Daftar isi dan tabel dihitung terpisah; satu kode dapat mempunyai beberapa tabel/varian. Entri rujukan belum menjamin tersedianya seluruh koefisien. Harga dasar contoh PDF tidak dijadikan harga proyek otomatis.</p><a href="data/ahs-coverage.json" download>Unduh laporan cakupan</a></details><div class="catalog-tools"><label class="title-filter"><span>⌕</span><input id="catalog-query" type="search" placeholder="Cari seluruh kode, alias, atau uraian pekerjaan…" value="${esc(query)}"></label><select id="catalog-field" aria-label="Bidang AHS">${['Semua','Sumber Daya Air','Cipta Karya','Bina Marga'].map(f=>`<option ${field===f?'selected':''}>${f}</option>`).join('')}</select><select id="catalog-status" aria-label="Status AHS">${['Semua','verified','extracted','review','reference'].map(f=>`<option value="${f}" ${catalogStatus===f?'selected':''}>${f==='Semua'?'Semua status':catalogState({extractionStatus:f})}</option>`).join('')}</select></div><p id="catalog-count" role="status"></p><div id="catalog-results" class="ahs-grid"></div><div id="catalog-more"></div>${smkkAnalysisView(project())}`;}
const fieldName=id=>({iv:'Sumber Daya Air',vi:'Cipta Karya',v:'Bina Marga',empiris:'Empiris'}[id]||'Manual');
const catalogMatches=(a,words)=>words.every(w=>(a.code+' '+(a.aliases||[]).join(' ')+' '+a.title).toLowerCase().includes(w));
function filterCatalog(){const words=query.toLowerCase().trim().split(/\s+/);const matches=catalog.filter(a=>(field==='Semua'||fieldName(a.docId)===field)&&(catalogStatus==='Semua'||a.extractionStatus===catalogStatus)&&catalogMatches(a,words));$('#catalog-count').textContent=`${fmt(matches.length)} hasil · menampilkan ${fmt(Math.min(catalogLimit,matches.length))}`;$('#catalog-results').innerHTML=matches.slice(0,catalogLimit).map(a=>`<article class="ahs-card"><div class="card-label">${fieldName(a.docId)} <span>·</span> ${esc(a.unit||'Satuan perlu diperiksa')}</div><h3>${esc(a.title)}</h3><code>${esc(a.code)}</code><p>${catalogState(a)} · ${a.components.length} komponen · ${sourceLink(a)}</p>${a.note?`<p class="ahs-note">${esc(a.note)}</p>`:''}<div class="ahs-actions"><button class="text-action" data-preview="${a.id}">Lihat analisis →</button><button class="button" data-add="${a.id}">${a.extractionStatus==='verified'?'+ Tambah ke RAB':'Periksa & gunakan'}</button></div></article>`).join('')||'<div class="empty-state"><h3>Tidak ada hasil untuk pencarian ini.</h3><p>Coba kode atau uraian lain, atau ubah filter bidang/status.</p></div>';$('#catalog-more').innerHTML=matches.length>catalogLimit?'<button class="button subtle" data-action="catalog-more">Tampilkan 48 berikutnya</button>':'';}
function pricesView(){return header('Harga Satuan Dasar (HSD).','Form harga upah, bahan, peralatan, dan lain-lain mengikuti susunan workbook rujukan.','<a class="button subtle" href="#resources">Rekap sumber daya →</a><button class="button subtle" data-action="price-template">Ekspor / template HSD CSV ↓</button><button class="button subtle" data-action="print-hsd">Cetak HSD / PDF</button><button class="button" data-action="import-rates">Impor harga CSV ↑</button>')+formHeader(project(),'HARGA SATUAN DASAR (HSD)')+`<div class="rab-alert neutral">Harga SHB adalah pembanding. Harga satuan adalah harga yang digunakan dalam AHS. Keduanya dapat diisi terpisah; diskon, konversi satuan, dan penyesuaian tahun pada workbook tidak diterapkan otomatis. Tanggal harga: ${esc(project().date)}.</div><div class="catalog-tools"><label class="title-filter"><input id="price-query" type="search" value="${esc(priceQuery)}" placeholder="Cari nama sumber daya…" aria-label="Cari sumber daya"></label><select id="price-group" aria-label="Kelompok sumber daya">${['Semua',...groups].map(g=>`<option ${priceGroup===g?'selected':''}>${g}</option>`).join('')}</select></div><div id="price-results"></div>`;}
function filterPrices(){const rows=resources(project()).filter(c=>(priceGroup==='Semua'||c.group===priceGroup)&&c.name.toLowerCase().includes(priceQuery.toLowerCase()));$('#price-results').innerHTML=rows.length?hsdForm(rows,project()):'<div class="empty-state"><h3>Belum ada sumber daya yang sesuai.</h3><p>Tambahkan pekerjaan ke RAB atau ubah filter.</p><a class="button" href="#catalog">Pilih AHS</a></div>';}
function resourceView(){const rows=resources(project());return header('Kebutuhan proyek, terurai.','Kuantitas sumber daya = jumlah koefisien × volume pekerjaan. Rekap ini belum termasuk rincian sumber daya SMKK.','<button class="button" data-action="resource-csv">Ekspor kebutuhan CSV ↓</button>')+(rows.length?`<div class="table-wrap"><table class="rab-table"><thead><tr><th>Sumber daya</th><th>Bidang / kelompok</th><th>Satuan</th><th>Total kebutuhan</th><th>Harga dasar</th><th>Nilai kebutuhan</th></tr></thead><tbody>${rows.map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${fieldName(c.docId)}<small>${c.group}</small></td><td>${esc(c.unit)}</td><td class="numeric">${fmt(c.quantity)}</td><td class="numeric">${c.price==null?'Belum diisi':rp(c.price)}</td><td class="numeric">${c.price==null?'—':rp(c.quantity*c.price)}</td></tr>`).join('')}</tbody></table></div><p class="setting-note">Nilai kebutuhan tidak memuat biaya umum, keuntungan, dan pajak. Pembulatan rekap kuantitas dapat menimbulkan selisih sen dengan pembulatan tiap baris AHS.</p>`:'<div class="empty-state"><h3>Belum ada kebutuhan sumber daya.</h3><a href="#catalog" class="button">Tambahkan pekerjaan</a></div>');}
function render(){nav();const v=view();main.classList.toggle('info-page',v==='project');main.innerHTML=v==='assistant'?header('Asisten AI','Analisis RAB dan diskusikan pekerjaan tanpa meninggalkan aplikasi.')+'<section id="ai-panel"></section>':v==='recap'?recapView():v==='project'?projectSettingsView():v==='quantity'?quantityView():v==='catalog'?catalogView():v==='prices'?pricesView():v==='resources'?resourceView():sheet();if(v==='assistant')mountAssistant($('#ai-panel'),project);if(v==='catalog'){filterCatalog();if(pendingSmkkFocus){pendingSmkkFocus=false;requestAnimationFrame(()=>{main.querySelector('#smkk-ahs')?.scrollIntoView({block:'start'});main.querySelector('[data-action="toggle-smkk"]')?.focus({preventScroll:true});});}}if(v==='prices')filterPrices();document.title=`${names[v]} — RAB Studio 2026`;}
let refreshTimer;
function refreshAfterEdit() {
  clearTimeout(refreshTimer);
  refreshTimer = setTimeout(() => {
    const focused = document.activeElement;
    const tableScroll=[...main.querySelectorAll('.table-wrap')].map(el=>[el.scrollLeft,el.scrollTop]);
    const attrs = ['data-setting','data-rate','data-volume','data-smkk','data-key','data-item-group','data-action','data-analysis','data-row-text','data-row-level','data-hsd-key','data-field','data-q-row','data-q-field','data-q-dimension','data-smkk-parameter'];
    const selector = focused.id ? '#' + CSS.escape(focused.id) : attrs.filter(a => focused.hasAttribute(a)).map(a => '[' + a + '="' + CSS.escape(focused.getAttribute(a)) + '"]').join('');
    const inside = dialog.open && !$('#create-project-form') && !$('#manual-form') && !$('#picker-query') && !$('#component-form');
    render();
    main.querySelectorAll('.table-wrap').forEach((el,i)=>{if(tableScroll[i]){el.scrollLeft=tableScroll[i][0];el.scrollTop=tableScroll[i][1];}});
    if (inside) analysis(dialog.dataset.item, dialog.dataset.preview === 'true');
    if (selector) document.querySelector(selector)?.focus({preventScroll:true});
  }, 0);
}
function closeMenu(){$('#sidebar').classList.remove('open');$('#nav-overlay').hidden=true;$('#menu-button').setAttribute('aria-expanded','false');}
function addItem(id){const a=catalog.find(a=>a.id===id);if(!a)return;if(a.extractionStatus&&a.extractionStatus!=='verified'){reviewAhs(id);return;}project().items.push({...structuredClone(a),id:crypto.randomUUID(),volume:1,group:fieldName(a.docId),manual:false,wbsLevel:2,remarks:''});save();nav();notify('Pekerjaan ditambahkan. Isi volume di Lembar RAB dan lengkapi harga dasar.');}
function analysis(id,preview=false){if(preview){const a=catalog.find(a=>a.id===id);if(a?.extractionStatus&&a.extractionStatus!=='verified'){reviewAhs(id);return;}}const item=preview?catalog.find(a=>a.id===id):project().items.find(a=>a.id===id);if(!item)return;const r=calculateItem(item,project().rates,project().overhead);$('#analysis-content').innerHTML=`<div class="analysis-head"><div><h2 id="analysis-title">Form Analisa Harga Satuan</h2><p>${sourceLink(item)} ${item.empirical?' · EMPIRIS':item.adjusted?' · AHS DISESUAIKAN':item.manual?' · ANALISIS MANUAL':''}</p></div><button class="icon-button" data-close-dialog aria-label="Tutup analisis">×</button></div>${formHeader(project(),'ANALISA HARGA SATUAN (AHS)')}${item.note?`<div class="rab-alert neutral">${esc(item.note)}</div>`:''}${ahsForm(item,r,project(),!preview)}<p class="setting-note">${r.missing?`${r.missing} harga belum diisi. Hasil masih parsial. `:''}${item.empirical?'Koefisien berasal dari pengamatan/perhitungan pengguna. Gunakan tombol Ubah AHS Empiris untuk memperbaruinya.':item.adjusted?'Komponen telah disesuaikan pengguna pada salinan proyek; periksa kembali kesesuaian dengan sumber.':'Koefisien sumber dikunci; tombol +/− membuat penyesuaian pada salinan proyek.'} Harga dan kode komponen terhubung ke HSD proyek.</p><div class="dialog-actions">${item.empirical?`<button class="button" data-empirical-edit="${item.id}">Ubah AHS Empiris</button>`:''}<button class="button subtle" data-print-ahs="${item.id}" data-preview="${preview}">Cetak AHS / PDF</button>${preview?`<button class="button" data-add="${item.id}" data-close-after>+ Tambah ke RAB</button>`:''}</div>`;dialog.dataset.item=id;dialog.dataset.preview=String(preview);if(!dialog.open)dialog.showModal();}
function manualForm(empirical=false,existing=null,targetId='') {
  manualRows=existing?.components?.length?structuredClone(existing.components):[{group:'Tenaga kerja',name:'',unit:'OH',coefficient:''}];
  $('#analysis-content').innerHTML=`<div class="analysis-head"><div><div class="eyebrow">${empirical?'ANALISIS BERDASARKAN PENGAMATAN PENGGUNA':'ANALISIS TAMBAHAN PROYEK'}</div><h2 id="analysis-title">${empirical?(existing?'Ubah AHS Empiris':'Buat AHS Empiris'):'Masukkan AHS manual'}</h2></div><button class="icon-button" data-close-dialog aria-label="Tutup">×</button></div><form id="manual-form" data-empirical="${empirical}" data-edit-id="${existing?.id||''}" data-target-id="${targetId}"><div class="settings-grid"><label>Kode pekerjaan<input name="code" required maxlength="100" value="${empirical?'Empiris':esc(existing?.code||'')}" ${empirical?'readonly':''}></label><label>Uraian pekerjaan<input name="title" required maxlength="1000" value="${esc(existing?.title||'')}"></label><label>Satuan hasil<input name="unit" required placeholder="m³ / m² / m / buah" maxlength="30" value="${esc(existing?.unit||'')}"></label>${empirical?'':`<label>Dokumen rujukan<select name="docId">${documents.map(d=>`<option value="${d.id}">${esc(d.label)} — ${esc(d.title)}</option>`).join('')}</select></label><label>Halaman PDF sumber<input name="page" type="number" min="1" max="10000" value="1" required></label>`}<label>Kelompok RAB<input name="group" value="${esc(existing?.group||(empirical?'Pekerjaan empiris':'Pekerjaan tambahan'))}" required maxlength="100"></label></div><p class="setting-note">${empirical?'Gunakan untuk pekerjaan yang belum tersedia dalam daftar. Isi komponen, koefisien kebutuhan per satuan hasil, dan dasar pengamatan/perhitungan Anda. Analisis diberi kode tetap Empiris dan tidak dinyatakan sebagai AHS dari SE.':'Salin seluruh komponen, koefisien, dan satuan dari dokumen rujukan. Analisis diberi label manual.'} Harga dasar diisi pada HSD.</p><div id="manual-rows"></div><button type="button" class="button subtle" data-action="manual-row">+ Komponen</button><label class="manual-note">${empirical?'Dasar empiris / asumsi produktivitas':'Asumsi / catatan sumber'}<textarea name="note" maxlength="4000" ${empirical?'required':''} placeholder="${empirical?'Hasil pengamatan lapangan, jumlah tenaga/alat, produksi per hari, dan dasar koefisien…':'Metode kerja, spesifikasi, kondisi lapangan…'}">${esc(existing?.note||'')}</textarea></label><div class="dialog-actions"><button class="button" type="submit">${empirical&&existing?'Simpan perubahan AHS Empiris':'Simpan pekerjaan ke RAB'}</button></div></form>`;
  paintManualRows();if(!dialog.open)dialog.showModal();
}
function download(filename,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
const filename=()=>project().name.replace(/[^\p{L}\p{N}_-]+/gu,'-').slice(0,80)||'RAB';
