document.addEventListener('click',e=>{try{const b=e.target.closest('button,[data-action]');if(!b)return;if(b.dataset.action){actions[b.dataset.action]?.();return;}if(b.hasAttribute('data-close-dialog')){dialog.close();return;}if(b.dataset.wbsShift){shiftWbs(b.dataset.wbsShift,Number(b.dataset.direction));return;}if(b.dataset.insertMenu){insertMenu(b.dataset.insertMenu);return;}if(b.dataset.insertScope){dialog.close();addBlank(true,b.dataset.insertScope,true);return;}if(b.dataset.insertWork){dialog.close();addBlank(false,b.dataset.insertWork,false,Number(b.dataset.level)||2);return;}if(b.hasAttribute('data-quantity-add')){addQuantity();return;}if(b.hasAttribute('data-quantity-apply')){applyQuantity();return;}if(b.dataset.quantityEdit!=null){addQuantity({mode:'edit',index:Number(b.dataset.quantityEdit)});return;}if(b.dataset.quantitySegment!=null){addQuantity({mode:'add',index:Number(b.dataset.quantitySegment)});return;}if(b.dataset.quantityGroupDelete!=null){const item=quantityWork(project(),quantitySelectedId),index=Number(b.dataset.quantityGroupDelete),row=item?.quantityRows?.[index];if(row){item.quantityRows=item.quantityRows.filter((r,i)=>row.groupId?r.groupId!==row.groupId:i!==index);syncQuantity(item);save();render();}return;}if(b.dataset.quantityDelete!=null){deleteQuantity(Number(b.dataset.quantityDelete));return;}if(b.dataset.componentAdd){componentEditor(b.dataset.componentAdd,b.dataset.group,b);return;}if(b.dataset.componentRemove){removeComponent(b.dataset.componentRemove,Number(b.dataset.index));return;}if(b.dataset.componentLast){const item=project().items.find(i=>i.id===b.dataset.componentLast);if(item){const index=item.components.findLastIndex(c=>c.group===b.dataset.group);removeComponent(item.id,index);}return;}if(b.hasAttribute('data-component-cancel')){b.closest('tr').remove();return;}if(b.dataset.manualGroup){if(manualRows.length>=300)throw Error('Maksimal 300 komponen.');manualRows.push({group:b.dataset.manualGroup,name:'',unit:b.dataset.manualGroup==='Tenaga kerja'?'OH':'',coefficient:''});paintManualRows();return;}if(b.dataset.manualLast){const index=manualRows.findLastIndex(c=>c.group===b.dataset.manualLast);if(index>=0)manualRows.splice(index,1);paintManualRows();return;}if(b.dataset.empiricalEdit){manualForm(true,project().items.find(i=>i.id===b.dataset.empiricalEdit));return;}if(b.dataset.printAhs){const item=b.dataset.preview==='true'?catalog.find(a=>a.id===b.dataset.printAhs):project().items.find(a=>a.id===b.dataset.printAhs);if(item)printHtml(formHeader(project(),'ANALISA HARGA SATUAN (AHS)')+ahsForm(item,calculateItem(item,project().rates,project().overhead),project(),false));return;}if(b.dataset.chooseAhs){pickAhs(b.dataset.chooseAhs);return;}if(b.dataset.bindAhs){bindAhs(b.dataset.bindAhs);return;}if(b.dataset.move){const i=project().items.findIndex(x=>x.id===b.dataset.move),j=i+Number(b.dataset.direction);if(j>=0&&j<project().items.length){[project().items[i],project().items[j]]=[project().items[j],project().items[i]];save();render();}return;}if(b.dataset.add){addItem(b.dataset.add);if(b.hasAttribute('data-close-after'))dialog.close();return;}if(b.dataset.preview){analysis(b.dataset.preview,true);return;}if(b.dataset.analysis){analysis(b.dataset.analysis);return;}if(b.dataset.delete){const item=project().items.find(i=>i.id===b.dataset.delete);project().items=project().items.filter(i=>i!==item);save();render();notify('Pekerjaan dihapus. Harga dasar tetap tersimpan.');return;}if(b.dataset.smkkGroupToggle){const g=b.dataset.smkkGroupToggle;if(smkkOpenGroups.has(g))smkkOpenGroups.delete(g);else smkkOpenGroups.add(g);render();return;}if(b.dataset.smkkGroupAdd){addSmkkComponent(b.dataset.smkkGroupAdd);return;}if(b.dataset.smkkDelete){project().smkk=project().smkk.filter(s=>s.id!==b.dataset.smkkDelete);save();render();return;}if(b.dataset.manualRemove){manualRows.splice(Number(b.dataset.manualRemove),1);paintManualRows();}}catch(err){notify(err.message);}});
document.addEventListener('click',e=>{const link=e.target.closest('[data-open-quantity]');if(link)quantitySelectedId=link.dataset.openQuantity;});
document.addEventListener('toggle',e=>{if(e.target.id==='compact-project')compactProjectOpen=e.target.open;},true);
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.informationField){updateInformationField(t);return;}if(t.dataset.rowText&&t.dataset.key==='title'){const item=project().items.find(i=>i.id===t.dataset.rowText);if(item&&(item.wbsLevel??2)===1){const start=t.selectionStart,end=t.selectionEnd;t.value=t.value.toLocaleUpperCase('id');t.setSelectionRange(start,end);}}if(t.id==='picker-query'){pickerLimit=48;filterPicker(t.value);return;}if(t.id==='catalog-query'){query=t.value;catalogLimit=48;filterCatalog();}if(t.id==='price-query'){priceQuery=t.value;filterPrices();}if(t.dataset.manual!=null){manualRows[Number(t.dataset.manual)][t.dataset.key]=t.value;}});
document.addEventListener('change',async e=>{const t=e.target;try{
  if(t.dataset.recapVolume){const value=nonnegative(t.value);if(t.value.trim()==='')throw Error('Volume paket wajib diisi.');const key=t.dataset.recapVolume;if(key==='__smkk__')project().smkkRecapVolume=value;else if(key==='unassigned')project().recapUnassignedVolume=value;else{const item=project().items.find(i=>i.id===key);if(!item)throw Error('Lingkup tidak ditemukan.');item.recapVolume=value;}save();refreshAfterEdit();return;}
  if(t.id==='smkk-risk'){switchSmkkRisk(t.value);return;}if(t.dataset.smkkParameter){updateSmkkSettings(t);return;}
  if(t.id==='quantity-work'){quantitySelectedId=t.value;render();return;}
  if(t.dataset.qRow!=null){editQuantity(t);return;}
  if(t.dataset.manual!=null&&t.dataset.key==='group'){manualRows[Number(t.dataset.manual)].group=t.value;paintManualRows();return;}
  if(t.id==='tax-scheme'){project().taxScheme=t.value;if(t.value==='dpp11of12')project().tax=12;save();refreshAfterEdit();return;}
  if(t.dataset.informationField){updateInformationField(t);return;}
  if(t.id==='saved-information-project'&&t.value!==''){active=Number(t.value);save();enterInformationForm();return;}
  if(t.id==='document-type'){project().documentType=t.value;save();refreshAfterEdit();return;}if(t.id==='project-select'){active=Number(t.value);save();render();return;}
  if(t.id==='catalog-field'){field=t.value;catalogLimit=48;filterCatalog();return;}if(t.id==='catalog-status'){catalogStatus=t.value;catalogLimit=48;filterCatalog();return;}if(t.id==='price-group'){priceGroup=t.value;filterPrices();return;}
  if(t.dataset.hsdKey){const key=t.dataset.hsdKey,field=t.dataset.field;project().resourceMeta??={};const meta=project().resourceMeta[key]??={};if(field==='shb'){if(t.value==='')delete meta.shb;else meta.shb=nonnegative(t.value);}else meta[field]=t.value.slice(0,field==='code'?100:4000);}
  else if(t.dataset.rowText){const item=project().items.find(i=>i.id===t.dataset.rowText);item[t.dataset.key]=(t.dataset.key==='title'&&(item.wbsLevel??2)===1?t.value.toLocaleUpperCase('id'):t.value).slice(0,t.dataset.key==='remarks'?4000:2000);}
  else if(t.dataset.setting){const key=t.dataset.setting;const v=['overhead','tax'].includes(key)?nonnegative(t.value):t.value.trim();if(['overhead','tax'].includes(key)&&v>100)throw Error('Persentase maksimal 100.');if(key==='name'&&!v)throw Error('Nama proyek wajib diisi.');project()[key]=v;}
  else if(t.dataset.volume){const item=project().items.find(i=>i.id===t.dataset.volume);item.volume=nonnegative(t.value);item.quantityLinked=false;}
  else if(t.dataset.itemGroup){if(!t.value.trim())throw Error('Kelompok tidak boleh kosong.');project().items.find(i=>i.id===t.dataset.itemGroup).group=t.value.trim();}
  else if(t.dataset.rate){if(t.value==='')delete project().rates[t.dataset.rate];else project().rates[t.dataset.rate]=nonnegative(t.value);save();refreshAfterEdit();return;}
  else if(t.dataset.smkk){const s=project().smkk.find(s=>s.id===t.dataset.smkk);if(!s)return;const key=t.dataset.key;if(key==='enabled'){s.enabled=t.checked;s.manualEnabled=true;}else if(['name','unit'].includes(key)){if(!t.value.trim())throw Error('Uraian dan satuan wajib diisi.');s[key]=t.value.trim();}else if(['price','volume'].includes(key)){s[key]=t.value===''?null:nonnegative(t.value);s[key==='price'?'manualPrice':'manualVolume']=true;}else return;}
  else if(t.id==='project-import'&&t.files[0]){const file=t.files[0];if(file.size>5e6)throw Error('Cadangan maksimal 5 MB.');if(projects.length>=100)throw Error('Maksimal 100 proyek.');const json=JSON.parse(await file.text());if(json.version!==1)throw Error('Versi cadangan tidak didukung.');const p=validateProject(json.project);p.items.forEach(i=>{i.manual=true;});projects.push(p);active=projects.length-1;notify('Cadangan diimpor sebagai proyek baru. Analisis impor diberi label manual untuk ditinjau.');t.value='';dialog.close();enterInformationForm();}
  else if(t.id==='rates-import'&&t.files[0]){if(t.files[0].size>5e6)throw Error('CSV maksimal 5 MB.');const result=importRates(await t.files[0].text(),project());project().rates=result.rates;project().resourceMeta=result.resourceMeta;notify(`${result.count} harga dasar diimpor.`);t.value='';}
  else return;save();refreshAfterEdit();
}catch(err){notify(err.message);if(t.type==='file')t.value='';else if(!dialog.open)render();}});
document.addEventListener('submit',e=>{
 if(e.target.id==='general-information-form'){e.preventDefault();return;}

 if(e.target.id==='create-project-form'){e.preventDefault();try{if(projects.length>=100)throw Error('Maksimal 100 proyek.');const name=new FormData(e.target).get('projectName').trim();if(!name)throw Error('Nama project wajib diisi.');projects.push(newProject(name));active=projects.length-1;save();dialog.close();location.hash='#project';render();notify('Project baru dibuat.');}catch(err){notify(err.message);}return;}

 if(e.target.id==='component-form'){e.preventDefault();saveComponent(e.target);return;}
 if(e.target.id!=='manual-form')return;e.preventDefault();
 try {
  const form=e.target;if(form.dataset.sourceReview&&!form.querySelector('[name=sourceChecked]').checked)throw Error('Periksa seluruh komponen dan koefisien terhadap sumber terlebih dahulu.');const f=new FormData(form),empirical=form.dataset.empirical==='true';
  const doc=empirical?null:documents.find(d=>d.id===f.get('docId')),page=empirical?1:Number(f.get('page'));
  if(!empirical&&(!doc||!Number.isInteger(page)||page<1||page>doc.pages))throw Error('Halaman sumber tidak valid.');
  if(!manualRows.length)throw Error('Tambahkan setidaknya satu komponen.');
  const note=f.get('note').trim();if(empirical&&!note)throw Error('Isi dasar pengamatan/perhitungan empiris.');
  const item={id:crypto.randomUUID(),code:empirical?'Empiris':f.get('code').trim(),title:f.get('title').trim(),unit:f.get('unit').trim(),group:f.get('group').trim(),docId:doc?.id||'',page,note,empirical,volume:1,manual:true,components:manualRows.map(r=>({...r,name:r.name.trim(),unit:r.unit.trim(),coefficient:nonnegative(r.coefficient)}))};
  const checked=validateProject({...project(),items:[item]}).items[0];
  const target=project().items.find(i=>i.id===(form.dataset.editId||form.dataset.targetId));
  if(target){const preserved={id:target.id,volume:target.volume,wbsLevel:target.wbsLevel??2,remarks:target.remarks||'',quantityRows:target.quantityRows||[],quantityLinked:Boolean(target.quantityLinked)};if(!form.dataset.editId&&target.title.trim())checked.title=target.title;Object.assign(target,checked,preserved);syncQuantity(target);}
  else project().items.push(checked);
  save();dialog.close();location.hash='#rab';render();notify(empirical?'AHS Empiris disimpan. Lengkapi harga dasar pada HSD.':'Analisis manual ditambahkan. Lengkapi harga dasar.');
 }catch(err){notify(err.message);}
});
